"""Counting semaphore source lessons; execution model still pending."""
ROWS = [
('Semaphore 구조·남은 허가 수와 대기 리스트', 'include/linux/semaphore.h', 'semaphore',
 'semaphore는 raw spinlock, unsigned int count와 wait_list를 가집니다. count는 현재 추가로 획득할 수 있는 허가 수이며 잠든 task 수가 아닙니다. count가 양수이면 down 계열은 잠금 아래 하나 소비하고, 0이면 대기 항목을 연결하는 느린 경로를 사용합니다. raw 잠금은 count와 리스트 변경을 보호하며 task가 잠든 전체 기간 동안 보유하는 것은 아닙니다.',
 '동시에 사용할 수 있는 유한 자원 수를 초기 count로 표현하고 획득과 반환을 대응시키세요. 멤버를 임의로 변경하지 말고 API로 사용합니다. 잠금 보호, 허가 소비와 실제 자원 사용을 서로 구분합니다.',
 [('count는 무엇을 표현하나요?', '추가로 획득할 수 있는 허가 수입니다.', '언제나 잠든 task의 정확한 수입니다.', '원문 주석은 count를 남은 획득 수로 설명합니다. 대기 task는 별도 리스트에 연결됩니다.'),
  ('수면 중에도 raw spinlock을 계속 보유하나요?', '아닙니다. 실제 대기 전에 풀고 다시 잡습니다.', '맞습니다. 모든 down이 raw 잠금 안에서 잠듭니다.', '빠른 count 갱신과 느린 수면은 보호 구간이 다릅니다. 느린 공통 함수의 unlock·schedule·lock 순서를 확인하세요.')]),
('Semaphore 초기화·입력과 lockdep 연결', 'include/linux/semaphore.h', 'sema_init',
 'sema_init은 지정 count, raw 잠금과 자기 참조 리스트를 가진 구조체를 대입하고 lockdep map을 초기화합니다. DEFINE_SEMAPHORE는 이름과 초기 수를 받는 정적 선언입니다. 입력 val은 int이고 저장 필드는 unsigned int이므로 음수나 잘못된 범위를 자동으로 유효한 자원 수로 고치는 함수는 아닙니다. 전체 구조체 초기화는 기존 대기 항목을 보존하지 않습니다.',
 '사용 전 유효한 음수가 아닌 허가 수를 정하세요. 사용 중인 semaphore를 재초기화하여 대기자를 잃지 않도록 합니다. 정적 선언의 초기값과 실행 중 초기화의 lockdep 분류를 함께 확인합니다.',
 [('sema_init이 음수 입력을 자동으로 0으로 제한하나요?', '아닙니다. 초기 count에 대입합니다.', '맞습니다. 모든 잘못된 입력을 clamp합니다.', '본문에는 음수 검사나 clamp 분기가 없습니다. 자료형 변환과 올바른 입력 계약을 확인해야 합니다.'),
  ('초기화는 사용 중인 대기 리스트를 보존하나요?', '아닙니다. 새 빈 리스트 상태를 구성합니다.', '맞습니다. 모든 task를 자동으로 옮깁니다.', '구조체 초기화 대입은 기존 연결을 순회하거나 옮기지 않습니다. 초기화와 경쟁 중 상태 변경은 구별하세요.')]),
('Semaphore 소유자 없음·binary와 mutex의 차이', 'include/linux/semaphore.h', 'DEFINE_SEMAPHORE',
 '초기 허가 수 1인 binary semaphore도 mutex처럼 소유 task를 기록하지 않습니다. 헤더는 down을 수행한 task와 다른 task가 up을 수행할 수 있다고 명시합니다. up과 down_trylock은 IRQ 문맥에서도 사용할 수 있는 계약입니다. 소유자 규칙이 없는 대신 호출자가 허가 반환과 자원 사용의 프로토콜을 지켜야 하며, 이름만으로 mutex의 소유자 검사나 우선순위 상속을 기대하면 안 됩니다.',
 '허가의 소비·반환 주체와 보호할 자원을 명확히 정하세요. 다른 문맥의 up이 필요한 사건인지 확인합니다. 일반적인 소유자 기반 상호 배제와 완료 통지의 목적은 mutex 및 completion 원리와 비교합니다.',
 [('up은 반드시 마지막 down을 수행한 같은 task가 호출해야 하나요?', '아닙니다. 소유자 규칙이 없습니다.', '맞습니다. 항상 mutex 소유자 검사와 같습니다.', '헤더는 다른 task나 IRQ 문맥에서의 반환을 허용합니다. 소유자 없는 counting 구조의 호출자 프로토콜이 필요합니다.'),
  ('count 1이면 mutex의 모든 사용 규칙도 자동으로 같나요?', '아닙니다. 소유자와 API 계약이 다릅니다.', '맞습니다. 자료구조와 디버그 규칙이 동일합니다.', 'binary라는 허가 수만으로 owner 기반 mutex가 되지는 않습니다. 실제 구조체와 반환 주체 규약을 확인하세요.')]),
('Semaphore down·빠른 소비와 uninterruptible 대기', 'kernel/locking/semaphore.c', 'down',
 'down은 might_sleep 뒤 irqsave raw 잠금 아래 count를 검사합니다. 양수이면 하나 줄이고, 0이면 __down의 TASK_UNINTERRUPTIBLE 대기로 들어갑니다. 그 뒤 이전 IRQ 상태를 복구합니다. 고정 버전의 원문은 이 일반 down 사용을 deprecated로 설명하고 interruptible 또는 killable을 안내합니다. 내부 irqsave 사용만으로 임의 IRQ 문맥에서 수면해도 되는 것은 아닙니다.',
 '잠들 수 있는 문맥과 사건 중단 요구를 확인하세요. count가 양수인 빠른 경로와 실제 수면 경로를 구별합니다. 커널 내부의 반드시 성공하는 특수 문맥 언급을 일반 IRQ 사용 허가로 확대하지 않습니다.',
 [('count가 양수이면 down은 무엇을 하나요?', '잠금 아래 count를 하나 소비합니다.', '항상 먼저 스택 waiter를 등록합니다.', '빠른 분기는 count 감소만 수행합니다. 대기 항목과 수면은 허가가 없는 느린 경로에서 사용합니다.'),
  ('irqsave가 있으므로 down을 임의 IRQ 문맥에서 잠들게 해도 되나요?', '아닙니다. 수면 가능한 사용 문맥이 필요합니다.', '맞습니다. raw 잠금이 scheduler를 대신합니다.', 'irqsave는 자료구조 보호의 문맥을 다룹니다. task 수면의 허용 조건을 자동으로 바꾸는 기능이 아닙니다.')]),
('Semaphore interruptible·허가 우선과 -EINTR', 'kernel/locking/semaphore.c', 'down_interruptible',
 'interruptible down은 count가 양수이면 먼저 소비하여 0을 반환합니다. pending signal 검사는 허가가 없는 느린 대기의 반복문에서 수행합니다. 그 대기가 signal로 중단되면 항목을 제거하고 -EINTR을 반환합니다. 일반 waitqueue나 completion의 -ERESTARTSYS와 다른 계약입니다. 이미 허가가 준비되어 있으면 signal이 있어도 빠른 획득 성공이 가능할 수 있습니다.',
 '성공 0과 음수 오류를 확인하여 획득하지 못한 자원을 사용하지 마세요. signal 상태와 count 분기의 검사 순서를 따라갑니다. 다른 대기 API에서 본 오류 번호를 그대로 적용하지 않습니다.',
 [('허가가 없고 허용 signal로 대기가 중단되면 반환값은 무엇인가요?', '-EINTR입니다.', '항상 completion과 같은 -ERESTARTSYS입니다.', 'semaphore의 interrupted label은 -EINTR을 반환합니다. API별 오류 계약을 원문에서 확인해야 합니다.'),
  ('count가 양수인데 pending signal이 있으면 항상 획득 실패인가요?', '아닙니다. 빠른 허가 소비가 먼저입니다.', '맞습니다. 함수 입장에서 signal을 항상 먼저 검사합니다.', '외부 함수는 count 분기를 먼저 수행합니다. signal 검사는 느린 경로에 있으므로 분기별 검사 순서를 구별하세요.')]),
('Semaphore killable·fatal signal과 wrapper', 'kernel/locking/semaphore.c', 'down_killable',
 'killable down도 양수 count를 먼저 소비합니다. 느린 경로는 TASK_KILLABLE로 공통 함수를 실행하며 fatal signal에 의해 중단될 때 -EINTR을 반환합니다. 일반 interruptible과 같은 오류 번호라도 중단을 허용하는 signal 범위가 다릅니다. __down, __down_interruptible, __down_killable과 __down_timeout은 같은 공통 알고리즘에 state와 시간을 다르게 전달합니다.',
 'signal 분류와 상태 비트를 연결해 읽으세요. 성공과 실패의 허가 보유 상태를 추적합니다. wrapper의 이름보다 실제 공통 인자와 반환 자료형을 확인합니다.',
 [('killable과 interruptible은 같은 모든 signal을 허용하나요?', '아닙니다. 대기 state와 signal 범위가 다릅니다.', '맞습니다. 오류 번호가 같으면 상태도 같습니다.', 'TASK_KILLABLE과 TASK_INTERRUPTIBLE은 다른 state 계약입니다. 반환 코드의 동일성과 허용 사건 범위를 구별하세요.'),
  ('killable의 허가 획득 성공 반환값은 무엇인가요?', '0입니다.', '언제나 1입니다.', '외부 result는 성공에 0을 사용합니다. trylock의 실패 1과 다른 API의 boolean 성공을 섞지 마세요.')]),
('Semaphore trylock·0 성공과 signed 중간값', 'kernel/locking/semaphore.c', 'down_trylock',
 'down_trylock은 irqsave raw 잠금 아래 sem->count - 1을 int count에 저장하고 음수가 아니면 count를 갱신합니다. 반환은 count < 0이므로 0이 성공이고 1이 실패입니다. 원문은 spin_trylock과 mutex_trylock의 boolean 성공 방향과 반대라고 경고합니다. unsigned 저장 필드와 signed 중간값이 함께 있으므로 큰 범위의 잘못된 count를 일반적인 작은 허가 수와 같게 해석하지 않습니다.',
 '호출 결과의 0·1 방향을 명시적으로 확인하세요. IRQ 문맥에서 비차단 사용의 계약을 지킵니다. 초기 허가와 반환 횟수를 유한 자원 범위로 관리하고 자료형 변환의 동작을 추적합니다.',
 [('down_trylock의 0 반환은 무엇을 뜻하나요?', '허가 획득 성공입니다.', '허가 획득 실패입니다.', '원문은 성공 0, 실패 1을 명시합니다. spin이나 mutex trylock의 boolean 결과와 방향이 반대입니다.'),
  ('count 중간 지역 변수는 저장 필드와 같은 unsigned인가요?', '아닙니다. 지역 변수는 int입니다.', '맞습니다. 모든 count는 같은 unsigned 타입입니다.', '구조체 필드와 지역 선언을 함께 확인하세요. 뺄셈의 unsigned 계산과 int 저장이 판정에 영향을 줄 수 있습니다.')]),
('Semaphore timeout·-ETIME과 허가의 즉시 성공', 'kernel/locking/semaphore.c', 'down_timeout',
 'down_timeout은 count가 양수이면 timeout 값과 관계없이 빠른 소비 성공 0을 반환합니다. 허가가 없으면 TASK_UNINTERRUPTIBLE 공통 대기에 지정 jiffies를 전달합니다. 시간이 0 이하이면 대기 항목을 제거하고 -ETIME으로 끝납니다. 이 API는 성공에 잔여 시간을 반환하지 않으며 completion이나 wait_event timeout의 0·양수 계약과 다릅니다.',
 'int 반환의 0 성공과 -ETIME 실패를 처리하세요. 숫자 0을 모든 timeout API의 실패라고 일반화하지 않습니다. 시간 단위와 실제 느린 경로 진입 여부를 별도로 확인합니다.',
 [('down_timeout의 0 반환은 무엇을 뜻하나요?', '허가 획득 성공입니다.', '반드시 시간 만료입니다.', '이 API는 0 성공과 -ETIME 만료를 사용합니다. jiffies 잔여값을 반환하는 다른 대기 API와 구별해야 합니다.'),
  ('timeout 0이어도 count가 양수이면 성공할 수 있나요?', '그렇습니다. 빠른 count 소비입니다.', '아닙니다. timeout부터 항상 검사합니다.', '외부 함수는 count가 양수인지 먼저 검사합니다. timeout 검사는 허가가 없는 공통 느린 경로에서 수행합니다.')]),
('Semaphore 느린 대기·스택 waiter와 grant 우선', 'kernel/locking/semaphore.c', '___down_common',
 '느린 공통 함수는 스택 semaphore_waiter를 tail에 넣고 current와 up=false를 설정합니다. 반복에서 signal, 시간 만료를 검사한 뒤 대기 상태를 설정하고 잠금을 풀어 schedule_timeout합니다. 돌아와 잠금을 잡으면 waiter.up을 먼저 확인하여 true이면 성공 0을 반환합니다. 따라서 그 대기 중 허가가 전달되면 다음 반복의 signal·timeout 검사보다 grant 확인이 앞섭니다. 허가를 받지 못한 중단 경로는 자신의 항목을 제거합니다.',
 '등록, 수면, 재획득과 grant의 판정 순서를 표시하세요. 깨움만으로 성공한다고 가정하지 말고 up 플래그를 확인합니다. 지역 waiter의 수명은 리스트에서 제거되거나 grant 전달된 경로와 함께 추적합니다.',
 [('schedule에서 돌아온 뒤 가장 먼저 성공을 확인하는 표시는 무엇인가요?', 'waiter.up입니다.', '무조건 반환한 시간이 양수인지입니다.', '잠금 재획득 뒤 up이 true이면 바로 0을 반환합니다. grant 전달과 시간 잔여값을 별개로 추적해야 합니다.'),
  ('허가를 못 받고 signal 또는 timeout으로 끝나면 항목은 남나요?', '아닙니다. 자신의 링크를 제거합니다.', '맞습니다. up이 언젠가 제거할 때까지 남습니다.', '두 종료 label은 list_del을 수행합니다. 스택 waiter가 함수 반환 뒤 리스트에 남지 않도록 정리하는 경로입니다.')]),
('Semaphore up·빈 리스트 증가와 직접 허가 전달', 'kernel/locking/semaphore.c', 'up',
 'up은 irqsave raw 잠금 아래 리스트를 검사합니다. 비어 있으면 count를 하나 늘립니다. waiter가 있으면 __up이 첫 항목을 제거하고 waiter.up=true로 설정한 뒤 task를 깨웁니다. 이 경로에서는 count를 증가시키지 않으므로 이미 선택한 waiter에게 직접 허가가 전달됩니다. 새 task가 count의 증가를 먼저 소비하여 그 허가를 빼앗는 경로와 구별됩니다.',
 '반환을 현재 waiter에 직접 전달하는 경우와 향후 획득을 위해 저장하는 경우를 구별하세요. up은 소유자 검사를 하지 않으므로 호출자 프로토콜로 균형과 유한 허가 범위를 지킵니다. 함수가 임의 overflow를 막는 포화 counter라고 가정하지 않습니다.',
 [('waiter가 있으면 up이 먼저 count를 증가시키나요?', '아닙니다. 선택 waiter에 직접 grant를 줍니다.', '맞습니다. 모든 up이 count를 증가시킵니다.', '외부 분기는 __up을 호출하고 내부 함수는 항목 제거·up 표시·깨움을 수행합니다. 이 경로에는 count 증가가 없습니다.'),
  ('선택하는 waiter는 어디의 항목인가요?', '대기 리스트 첫 항목입니다.', '항상 마지막으로 등록된 항목입니다.', '__up은 list_first_entry를 사용합니다. tail 등록과 첫 항목 grant를 연결해 선택 순서를 이해하세요.')]),
('Semaphore 경합 추적·공통 wrapper와 고정 인자', 'kernel/locking/semaphore.c', '__down_common',
 '__down_common은 trace_contention_begin을 호출하고 실제 ___down_common의 결과를 얻은 뒤 trace_contention_end에 결과를 전달합니다. 바깥 __down 계열 wrapper는 state와 timeout을 고정하여 공통 알고리즘에 전달합니다. 원문은 inline 과정에서 상수 state와 시간 인자가 최적화될 수 있다고 설명합니다. tracepoint 호출은 실제 경합을 관측하는 연결점이며 자체가 허가 소비나 잠금 정책을 바꾸지는 않습니다.',
 '실제 대기 알고리즘과 그 앞뒤 계측 wrapper를 구별합니다. trace 이벤트에 성공·signal·timeout 결과가 어디서 전달되는지 따라갑니다. 사용자 공간 직렬 모델의 hook 기록을 실제 커널 ftrace나 시간 측정으로 주장하지 않습니다.',
 [('trace_contention_end에 전달하는 값은 무엇인가요?', '공통 대기의 반환 결과입니다.', '항상 초기 count만 전달합니다.', 'wrapper는 실제 함수의 ret를 받아 종료 이벤트에 전달합니다. 계측 정보와 알고리즘의 상태 변경을 구별하세요.'),
  ('inline wrapper의 고정 state 인자는 어떤 목적과 연결되나요?', '공통 경로의 상수 조건 최적화와 연결됩니다.', '모든 signal을 자동으로 삭제합니다.', '원문 주석은 상수 state와 timeout이 컴파일러에 의해 최적화될 수 있다고 설명합니다. API 동작은 선택된 실제 state 계약을 따릅니다.')])
]

ROWS.append((
 'Semaphore count 경계·unsigned 계산과 int 변환', 'kernel/locking/semaphore.c', 'down_trylock',
 '저장 count는 unsigned int이므로 count - 1은 unsigned 계산입니다. 결과를 int에 저장한 뒤 음수 여부로 try 획득을 판정합니다. 검증한 GNU C의 32비트 int 구성에서 count=INT_MAX+2를 주입하면 양수 저장 값인데도 int 중간값이 음수가 되어 실패합니다. up의 빈 리스트 분기에는 completion 같은 포화 guard가 없으므로 UINT_MAX 다음은 0으로 wrap합니다. 이것은 정상적인 균형 자원 사용 범위 밖의 경계 관찰이며 모든 플랫폼의 signed 변환 결과를 일반화하는 주장이 아닙니다.',
 '호출자는 유효한 초기 자원 수와 소비·반환 균형을 지키세요. 실제 프로그램에서 멤버를 직접 바꾸지 않습니다. unsigned 표현식, signed 저장과 비교를 단계로 나누어 C 자료형의 변환 원리를 읽습니다.',
 [('검증한 int32 구성의 count=INT_MAX+2 주입에서 try 결과는 무엇인가요?', '실패 1이며 저장 count는 유지됩니다.', '저장 값이 양수라서 모든 구성에서 항상 성공합니다.', '원문은 unsigned 뺄셈 결과를 int에 저장합니다. 선택한 컴파일러 문맥의 음수 중간값은 실패 분기를 선택합니다. 정상 자원 범위와 구별하세요.'),
  ('빈 리스트에서 UINT_MAX에 up을 하면 포화 값이 유지되나요?', '아닙니다. unsigned 증가가 0으로 wrap합니다.', '맞습니다. completion의 sentinel guard와 같습니다.', 'semaphore의 up 분기는 count++이며 포화 조건이 없습니다. 다른 primitive에서 본 overflow 방어를 자동으로 적용하지 마세요.')]))

def register(topic, q, detail):
    for title, path, symbol, principle, use, qa in ROWS:
        topic(title, '동기화', path, symbol,
              '원문 counting semaphore의 남은 허가 수와 FIFO grant, 잠금·수면·signal·timeout을 읽어 자원 제한 기술의 사용 조건을 배웁니다.',
              principle, use,
              'count, wait_list, waiter.up과 반환값을 따로 표시하고 잠금 해제·재획득 구간을 따라가세요.',
              *(q(*x) for x in qa), details=[
                  detail('원문 확인', '고정 Linux v6.12 semaphore.h와 kernel/locking/semaphore.c를 전체 읽고 함수별 분기와 사용 주석을 대조했습니다.'),
                  detail('검증 범위', '원문을 직렬 리스트·raw 잠금·IRQ·task·signal·스케줄러·trace hook 모델에 연결한 66,001건이 최적화 및 ASan·UBSan에서 각각 통과했습니다. 큰 count와 음수 초기값은 정상 자원 범위 밖의 주입 사례입니다. 실제 커널 경합·시간 상한·ftrace·SMP 검증은 아닙니다.')])
